-- Carreiras por area de interesse, com codigo RIASEC de 2 letras (base O*NET).
-- Usadas na recomendacao: compatibilidade = 2 x escore do 1o tipo + escore do 2o tipo.
CREATE TABLE career (
    id                 INTEGER      PRIMARY KEY,
    name               VARCHAR(100) NOT NULL,
    area               VARCHAR(30)  NOT NULL,
    primary_category   VARCHAR(20)  NOT NULL,
    secondary_category VARCHAR(20)  NOT NULL,
    description        VARCHAR(300) NOT NULL,
    CONSTRAINT uk_career_name_area UNIQUE (name, area)
);
CREATE INDEX idx_career_area ON career (area);

